Write {"file_path":"D:\code\ESI.ts\tests\bdd\step-definitions\core\mercenary.steps.ts","content":"import { defineFeature, loadFeature } from 'jest-cucumber';
import { EsiClient } from '../../../../src/EsiClient';
import { EsiError } from '../../../../src/core/util/error';
import { TestDataFactory } from '../../../../src/testing/TestDataFactory';

const feature = loadFeature('tests/bdd/features/core/mercenary.feature');

defineFeature(feature, (test) => {
  let client: EsiClient;

  beforeEach(() => {
    client = new EsiClient({
      clientId: 'test-client',
      baseUrl: 'https://esi.evetech.net',
      timeout: 5000,
    });
  });

  test('WHEN getMercenaryDens is called, the client shall return dens with development and anarchy data', ({ given, when, then }) => {
    let result: any;
    const expectedDens = [
      {
        den_id: 5001,
        system_id: 30000142,
        constellation_id: 20000125,
        region_id: 10000002,
        development_level: 3,
        anarchy_level: 2,
        active_operations: 1,
      },
      {
        den_id: 5002,
        system_id: 30004759,
        constellation_id: 20000690,
        region_id: 10000060,
        development_level: 5,
        anarchy_level: 4,
        active_operations: 3,
      },
    ];

    given('the ESI mercenary dens endpoint returns den data', () => {
      jest
        .spyOn(client.mercenary, 'getMercenaryDens')
        .mockResolvedValue(expectedDens as any);
    });

    when('getMercenaryDens is called', async () => {
      result = await client.mercenary.getMercenaryDens();
    });

    then('the client shall return dens with development_level and anarchy_level fields', () => {
      expect(result).toBeDefined();
      expect(result).toHaveLength(2);
      expect(result[0].den_id).toBe(5001);
      expect(result[0].development_level).toBe(3);
      expect(result[0].anarchy_level).toBe(2);
      expect(result[1].active_operations).toBe(3);
    });
  });

  test('WHEN getMercenaryDens returns no results, the client shall return an empty array', ({ given, when, then }) => {
    let result: any;

    given('the ESI mercenary dens endpoint returns no den data', () => {
      jest.spyOn(client.mercenary, 'getMercenaryDens').mockResolvedValue([]);
    });

    when('getMercenaryDens is called', async () => {
      result = await client.mercenary.getMercenaryDens();
    });

    then('the client shall return an empty array', () => {
      expect(Array.isArray(result)).toBe(true);
      expect(result).toHaveLength(0);
    });
  });

  test('WHEN getMercenaryTacticalOperations is called, the client shall return operation details with status', ({ given, when, then }) => {
    let result: any;
    const expectedOps = [
      {
        operation_id: 7001,
        den_id: 5001,
        system_id: 30000142,
        site_type: 'assault',
        status: 'active',
        started_at: '2026-05-20T10:00:00Z',
        expires_at: '2026-05-20T22:00:00Z',
      },
      {
        operation_id: 7002,
        den_id: 5002,
        system_id: 30004759,
        site_type: 'recon',
        status: 'spawning',
        started_at: '2026-05-20T14:00:00Z',
        expires_at: '2026-05-21T02:00:00Z',
      },
    ];

    given('the ESI mercenary tactical operations endpoint returns active operations', () => {
      jest
        .spyOn(client.mercenary, 'getMercenaryTacticalOperations')
        .mockResolvedValue(expectedOps as any);
    });

    when('getMercenaryTacticalOperations is called', async () => {
      result = await client.mercenary.getMercenaryTacticalOperations();
    });

    then('the client shall return operations with operation_id, status, and site_type fields', () => {
      expect(result).toBeDefined();
      expect(result).toHaveLength(2);
      expect(result[0].operation_id).toBe(7001);
      expect(result[0].status).toBe('active');
      expect(result[1].site_type).toBe('recon');
    });
  });

  test('WHEN dens and operations are fetched, the client shall enable correlation by den_id', ({
    given,
    when,
    then,
  }) => {
    let denResults: any;
    let opResults: any;
    const dens = [
      {
        den_id: 5001,
        system_id: 30000142,
        constellation_id: 20000125,
        region_id: 10000002,
        development_level: 3,
        anarchy_level: 2,
        active_operations: 1,
      },
    ];
    const ops = [
      {
        operation_id: 7001,
        den_id: 5001,
        system_id: 30000142,
        site_type: 'assault',
        status: 'active',
        started_at: '2026-05-20T10:00:00Z',
        expires_at: '2026-05-20T22:00:00Z',
      },
    ];

    given('the ESI mercenary dens and tactical operations endpoints return data', () => {
      jest
        .spyOn(client.mercenary, 'getMercenaryDens')
        .mockResolvedValue(dens as any);
      jest
        .spyOn(client.mercenary, 'getMercenaryTacticalOperations')
        .mockResolvedValue(ops as any);
    });

    when('getMercenaryDens and getMercenaryTacticalOperations are called', async () => {
      [denResults, opResults] = await Promise.all([
        client.mercenary.getMercenaryDens(),
        client.mercenary.getMercenaryTacticalOperations(),
      ]);
    });

    then('the client shall return operations whose den_id matches a parent den', () => {
      expect(denResults).toHaveLength(1);
      expect(opResults).toHaveLength(1);
      expect(opResults[0].den_id).toBe(denResults[0].den_id);
    });
  });

  test('IF ESI service is unavailable, THEN the client shall throw an EsiError with status 503', ({ given, when, then }) => {
    let caughtError: any;

    given('the ESI mercenary endpoint returns a 503 service unavailable error', () => {
      const error = TestDataFactory.createError(503);
      jest.spyOn(client.mercenary, 'getMercenaryDens').mockRejectedValue(error);
    });

    when('getMercenaryDens is called and the service is unavailable', async () => {
      try {
        await client.mercenary.getMercenaryDens();
      } catch (e) {
        caughtError = e;
      }
    });

    then('the client shall throw an EsiError with status 503', () => {
      expect(caughtError).toBeInstanceOf(EsiError);
    });
  });
});
"}
